SELECT p.name AS product_name, d.product_key, p.third_platform, p.device_node, p.store_policy, d.device_name, d.device_id, d.iot_id, d.state, d.device_address, split_part(COALESCE(d.coordinate, ''), ',', 1) AS longitude, split_part(COALESCE(d.coordinate, ''), ',', 2) AS latitude, d.signal_strength, d.device_tag, to_timestamp(d.create_time) AT TIME ZONE 'Asia/Shanghai' AS create_time, to_timestamp(d.online_time) AT TIME ZONE 'Asia/Shanghai' AS online_time, to_timestamp(d.registry_time) AT TIME ZONE 'Asia/Shanghai' AS registry_time, d.detail FROM iot_device d LEFT JOIN iot_product p ON d.product_key = p.product_key
AND d.iot_id LIKE CONCAT('%', #{ioTDevice.iotId}, '%')
AND d.device_id LIKE CONCAT('%', #{ioTDevice.deviceId}, '%')
AND d.product_key LIKE CONCAT('%', #{ioTDevice.productKey}, '%')
AND d.device_name LIKE CONCAT('%', #{ioTDevice.deviceName}, '%')
AND d.instance = #{ioTDevice.instance}
AND d.application = #{ioTDevice.application}
AND d.state = #{ioTDevice.state}
AND d.areas_id = #{ioTDevice.areasId}
ORDER BY d.create_time DESC LIMIT 200000

SELECT a.id AS id, up.app_unique_id AS applicationId, up.app_id, u.union_id AS userUnionId, u.id AS userId, a.tenant_id AS tenantId, a.device_id AS deviceId, a.device_name AS deviceName, a.coordinate AS coordinate, a.product_key AS productKey, a.product_name AS productName, dp.creator_id AS productCreatorId, a.ext_device_id AS extDeviceId, a.state AS state, a.iot_id AS iotId, a.registry_time AS registryTime, a.online_time AS onlineTime, a.gw_product_key AS gwProductKey, a.device_secret AS deviceSecret, CASE WHEN a.derive_metadata IS NULL OR a.derive_metadata = '' THEN dp.metadata ELSE a.derive_metadata END AS metadata, up.app_status AS appDisable, dp.third_platform AS thirdPlatform, dp.device_node AS deviceNode, dp.configuration AS configuration, dp.store_policy AS storePolicy, dp.store_policy_configuration AS storePolicyCfg, CASE WHEN da.id IS NULL THEN FALSE ELSE TRUE END AS shadow, tg.tag_value AS devGroupId, a.configuration AS devConfiguration, a.areas_id AS areasId, a.detail AS detail FROM iot_device a LEFT JOIN iot_product dp ON dp.product_key = a.product_key LEFT JOIN iot_user u ON a.creator_id = u.union_id LEFT JOIN iot_user_application up ON up.app_unique_id = a.application LEFT JOIN iot_device_shadow da ON da.iot_id = a.iot_id LEFT JOIN iot_device_tags tg ON tg.iot_id = a.iot_id AND tg.tag_key = 'devGroup'
AND a.product_key = #{productKey}
AND a.device_id = #{deviceId}
AND a.iot_id = #{iotId}
AND a.ext_device_id = #{extDeviceId}
AND a.gw_product_key = #{gwProductKey}
AND dp.third_platform = #{thirdPlatform}
LIMIT 1




