SELECT c.instance_key AS instanceKey, c.platform_device_id AS deviceId,
       c.tenant_id AS tenantId, COUNT(1) AS channelCount
FROM video_platform_channel c
WHERE (c.enabled = 1 OR c.enabled IS NULL)
  AND (

    (c.instance_key = #{device.instanceKey} AND c.platform_device_id = #{device.deviceId}

      AND c.tenant_id = #{device.tenantId}
      AND (c.tenant_id IS NULL OR c.tenant_id = '')
    )

  )
GROUP BY c.instance_key, c.platform_device_id, c.tenant_id

